def solve_sequence(N):
    """Computes the sequence a_n up to index N."""
    a = {}
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        a_n_minus_1 = a[n-1]

        # Since a_n is non-decreasing (conjectured and numerically verified), a_{n-1} is always defined and positive.
        # Also, since a_n is positive, a_n <= n, we have n - a_{n-1} >= 1.

        try:
            term1 = a[a_n_minus_1]
        except KeyError:
            # This should not happen if the sequence values remain within the computed range.
            print(f"Error: a_{a_n_minus_1} requested but not computed for n={n}")
            return a

        try:
            term2 = a[n - a_n_minus_1]
        except KeyError:
            # This should not happen if the sequence values remain within the computed range.
            print(f"Error: a_{n - a_n_minus_1} requested but not computed for n={n}")
            return a

        a[n] = term1 + term2
    return a

